def analyze_argument(sentence):
    # Define the possible tags
    tags = ['<claim>', '</claim>', '<premise>', '</premise>']

    # Split the sentence into words
    words = sentence.split()

    # Initialize variables to keep track of the current tag and span
    current_tag = None
    current_span = []

    # Iterate over the words
    for word in words:
        # Check if the word starts with a tag
        if word.startswith(tags[0]):
            # If so, update the current tag and reset the current span
            current_tag = word
            current_span = []
        elif word.endswith(tags[1]):
            # If so, end the current span and print it
            current_span.append(word)
            if current_tag == tags[0]:
                return''.join(current_span) +'' +''.join([word for word in words if word not in current_span])
            else:
                return''.join([word for word in words if word not in current_span]) +'' +''.join(current_span)
        # Add the word to the current span
        current_span.append(word)

    # If no closing tag is found, assume the last span is a premise
    if current_tag == tags[0]:
        return''.join(current_span) +''
    else:
        return''.join(words)


